package io.asv.odinlab;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.*;
import android.widget.*;
import java.io.*;
import java.nio.*;
import java.nio.file.Files;
import org.json.*;
public class MainActivity extends Activity {
 TextView status;final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);status=new TextView(this);status.setText("Odin Lab · codex/edscan-fastweb-diego\n24 combinaciones: detectores × Milo/Odin. Datos propios. Sin colección. Galerías distintas: similitud no equivale a precisión. Esquinitas aún no habilitado.");root.addView(status);Button camera=new Button(this);camera.setText("CameraX · 24 combinaciones");camera.setOnClickListener(v->startActivity(new Intent(this,LiveCameraActivity.class)));root.addView(camera);Button photo=new Button(this);photo.setText("Comparar foto · 24 combinaciones");photo.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),22));root.addView(photo);Button parity=new Button(this);parity.setText("Diagnóstico paridad Odin");parity.setOnClickListener(v->parity());root.addView(parity);setContentView(root);if(getIntent().getBooleanExtra("odinParity",false))parity();if(getIntent().getBooleanExtra("labSmoke",false))smoke();}
 void smoke(){worker.execute(()->{try{File dir=new File(getFilesDir(),"lab-smoke-"+System.currentTimeMillis());if(!dir.mkdirs())throw new IOException("mkdir");Bitmap b;try(InputStream in=getAssets().open("raw0.png")){b=BitmapFactory.decodeStream(in);}JSONArray rows=new JSONArray();try(LiveEngine e=new LiveEngine(this)){if(LiveEngine.COMBINATIONS.length!=24)throw new IOException("Expected24");for(int d=0;d<LiveEngine.DETECTORS.length;d++){LiveEngine.Detection det=e.detect(b,d,false);JSONObject row=new JSONObject().put("detector",LiveEngine.DETECTORS[d]).put("quads",LiveEngine.jsonQuads(det)).put("detect_ms",det.ms);int selected=LiveEngine.select(det,.5f,.5f);if(selected>=0){Bitmap c=LiveEngine.crop(b,det.quads.get(selected));try{row.put("milo",e.identify(c,true));row.put("odin",e.identify(c,false));}finally{c.recycle();}}rows.put(row);}}finally{b.recycle();}CaptureEngine.save(dir,"result.json",new JSONObject().put("rows",rows).put("complete",true));message("Smoke24 completado; no mide precisión: "+dir.getName());}catch(Exception ex){message(ex.toString());android.util.Log.e("OdinLab","smoke",ex);}});}
 void message(String s){runOnUiThread(()->status.setText(s));}
 void parity(){worker.execute(()->{try{File dir=new File(getFilesDir(),"odin-parity-"+System.currentTimeMillis());if(!dir.mkdirs())throw new IOException("mkdir");Bitmap b;try(InputStream in=getAssets().open("raw0.png")){b=BitmapFactory.decodeStream(in);}try(OdinIdentifier o=new OdinIdentifier(this)){CaptureEngine.png(new File(dir,"input.png"),b);JSONObject r=o.identify(b);for(String name:new String[]{"tensor","embedding"}){float[] values=name.equals("tensor")?o.lastTensor:o.lastEmbedding;ByteBuffer bytes=ByteBuffer.allocate(values.length*4).order(ByteOrder.LITTLE_ENDIAN);bytes.asFloatBuffer().put(values);Files.write(new File(dir,name+".bin").toPath(),bytes.array());}CaptureEngine.save(dir,"result.json",r);try(EsquinitasDetector e=new EsquinitasDetector(this)){CaptureEngine.save(dir,"esquinitas.json",e.run(b));ByteBuffer eb=ByteBuffer.allocate(e.lastInput.length*4).order(ByteOrder.LITTLE_ENDIAN);eb.asFloatBuffer().put(e.lastInput);Files.write(new File(dir,"esquinitas-tensor.bin").toPath(),eb.array());}message("Paridad calculada (pendiente validar PC): "+dir.getName());}finally{b.recycle();}}catch(Exception e){message(e.toString());android.util.Log.e("OdinLab","parity",e);}});}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=22||res!=RESULT_OK||data==null)return;var uri=data.getData();worker.execute(()->{try{Bitmap b=ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),uri),(decoder,info,source)->{decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);int w=info.getSize().getWidth(),h=info.getSize().getHeight();if(Math.max(w,h)>2048){float scale=2048f/Math.max(w,h);decoder.setTargetSize(Math.round(w*scale),Math.round(h*scale));}});File dir=new File(getFilesDir(),"photo-ab-"+System.currentTimeMillis());if(!dir.mkdirs())throw new IOException("mkdir");JSONArray rows=new JSONArray();CaptureEngine.png(new File(dir,"input.png"),b);try(LiveEngine engine=new LiveEngine(this)){for(int d=0;d<LiveEngine.DETECTORS.length;d++){message("Comparando "+LiveEngine.DETECTORS[d]);LiveEngine.Detection det=engine.detect(b,d,false);for(int k=0;k<det.quads.size();k++){Bitmap crop=LiveEngine.crop(b,det.quads.get(k));try{CaptureEngine.png(new File(dir,"crop-"+d+"-"+k+".png"),crop);for(boolean milo:new boolean[]{true,false})rows.put(new JSONObject().put("detector",LiveEngine.DETECTORS[d]).put("proposal",k).put("detect_ms",det.ms).put("quads",LiveEngine.jsonQuads(det)).put("identification",engine.identify(crop,milo)));}finally{crop.recycle();}}if(det.quads.isEmpty())rows.put(new JSONObject().put("detector",LiveEngine.DETECTORS[d]).put("no_proposal",true).put("detect_ms",det.ms));}}finally{b.recycle();}CaptureEngine.save(dir,"results.json",new JSONObject().put("rows",rows).put("note","Single pass, no warmup. Proposals are not ground truth."));message("Guardado: "+dir.getName());}catch(Exception e){message(e.toString());}});}
}
